TypeScript - typed error wrapper example:
interface RedwoodErrorMeta {
  error_code?: string;
  http_status?: number;
  retriable?: boolean;
  backoff_hint_ms?: number;
  operation_id?: string;
}
class RedwoodError extends Error {
  public meta: RedwoodErrorMeta;
  constructor(message: string, meta: RedwoodErrorMeta = {}) {
    super(message);
    this.meta = meta;
  }
}
// Usage in consumer:
try {
  await client.streamGenerate(...);
} catch (e) {
  if (e instanceof RedwoodError && e.meta.retriable) {
    // emit telemetry and retry with backoff_hint_ms
  }
}

Go - error wrapping and retry hint:
type ErrorMeta struct {
  ErrorCode string
  HTTPStatus int
  Retriable bool
  BackoffHintMs int64
  OperationID string
}

// Wrap transport error:
return nil, &redwood.Err{Message: "connection reset", Meta: ErrorMeta{ErrorCode: "transport.connection_reset", Retriable: true, BackoffHintMs: 800}}
